:root { font-family: system-ui, Avenir, Helvetica, Arial, sans-serif; line-height: 1.5; font-weight: 400; color-scheme: light dark; color: rgba(255, 255, 255, 0.87); font-synthesis: none; text-rendering: optimizelegibility; -webkit-font-smoothing: antialiased; }a { font-weight: 500; color: rgb(100, 108, 255); text-decoration: inherit; }a:hover { color: rgb(83, 91, 242); }body { margin: 0px; min-height: 100vh; }h1 { font-size: 3.2em; line-height: 1.1; }button { border-radius: 8px; border: 1px solid transparent; padding: 0.6em 1.2em; font-size: 1em; font-weight: 500; font-family: inherit; background-color: rgb(26, 26, 26); cursor: pointer; transition: border-color 0.25s; }button:hover { border-color: rgb(100, 108, 255); }button:focus, button:focus-visible { outline: -webkit-focus-ring-color auto 4px; }.main-container { min-height: 100vh; min-width: 100vw; }.main-container:nth-child(2) { background-color: rgb(116, 56, 56); }.main-container:nth-child(3) { background-color: rgb(37, 67, 92); }@media (prefers-color-scheme: light) {
  :root { color: rgb(33, 53, 71); background-color: rgb(255, 255, 255); }
  a:hover { color: rgb(116, 123, 255); }
  button { background-color: rgb(249, 249, 249); }
}

#root { text-align: center; }.logo { height: 6em; padding: 1.5em; will-change: filter; transition: filter 300ms; }.logo:hover { filter: drop-shadow(rgba(100, 108, 255, 0.667) 0px 0px 2em); }.logo.react:hover { filter: drop-shadow(rgba(97, 218, 251, 0.667) 0px 0px 2em); }@keyframes logo-spin { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}@media (prefers-reduced-motion: no-preference) {
  a:nth-of-type(2) .logo { animation: 20s linear 0s infinite normal none running logo-spin; }
}.card { padding: 2em; }.read-the-docs { color: rgb(136, 136, 136); }

